create table employee_contract
(
    base_salary      decimal(12, 2)                                                                                 null,
    end_date         date                                                                                           null,
    start_date       date                                                                                           null,
    created_at       datetime(6)                                                                                    not null,
    created_by       bigint                                                                                         null,
    employee_id      bigint                                                                                         not null,
    file_metadata_id bigint                                                                                         null,
    id               bigint                                                                                         not null
        primary key,
    signed_at        datetime(6)                                                                                    null,
    updated_at       datetime(6)                                                                                    null,
    updated_by       bigint                                                                                         null,
    file_key         varchar(255)                                                                                   null,
    contract_type    enum ('OFFICIAL', 'PROBATION', 'SEASONAL')                                                     null,
    salary_type      enum ('DAILY', 'HOURLY', 'MONTHLY')                                                            null,
    status           enum ('ACTIVE', 'DELETE', 'DRAFT', 'EXPIRED', 'INACTIVE', 'PENDING', 'REJECTED', 'UNASSIGNED') null,
    constraint UKdmf7wwub533gmgedp3prwus52
        unique (file_metadata_id),
    constraint FKg5xyt16am2rjlyu89c0vg9eq2
        foreign key (employee_id) references employee (user_id),
    constraint FKr3ia25oh0rlassid2eng7rcfd
        foreign key (file_metadata_id) references file_metadata (id)
);

